insert into private.academy_assessment_questions(question_id,assessment_id,position,prompt,options,correct_index)
values
  ('start-4','start',4,'A colleague''s workspace menu differs from yours. What is the best first explanation?','["Access reflects approved roles and departmental permissions","Their browser must be broken","They should borrow your account","Every employee must have identical privileges"]'::jsonb,0),
  ('start-5','start',5,'Before attaching a document, what should you confirm?','["That another employee has a similar file","The correct organization or project and authorized access","That the file is the largest available","That it can be posted publicly"]'::jsonb,1),
  ('start-6','start',6,'A work item has an assigned owner but no required evidence yet. What should you do?','["Delete it","Ask an unapproved volunteer to finish it","Read its requirements and gather permitted evidence before proposing completion","Mark it finished to clear the queue"]'::jsonb,2),
  ('start-7','start',7,'Your task shows a deadline in a different time zone. What is appropriate?','["Assume all international times use Detroit","Change every event to your local time","Ignore the deadline","Confirm the event''s time zone and the owner before acting"]'::jsonb,3),
  ('start-8','start',8,'You accidentally mark a practice lesson complete. What is the correction?','["Use the Academy''s own correction control; it is self-reported","Edit another person''s record","Delete the entire staff account","Treat the mistake as a professional credential"]'::jsonb,0),
  ('grants-4','grants',4,'A foundation excludes fiscal sponsors in its published eligibility requirements. What should you do?','["Document the restriction and seek an eligible opportunity or approved clarification","Submit with a different organization name","Hide HPG''s sponsorship relationship","Use a generic draft and ignore the rules"]'::jsonb,0),
  ('grants-5','grants',5,'The application budget conflicts with the signed funding arrangement. What comes first?','["Ask the NGO to skip its documented reporting obligations","Reconcile the budget and secure the proper approvals","Submit before the deadline without review","Move expenses to unrelated line items"]'::jsonb,1),
  ('grants-6','grants',6,'An NGO claims it has served 20,000 people, but no source is provided. What is appropriate?','["Increase it for impact","Remove all useful evidence from the proposal","Request supporting evidence or label the claim unverified","Quote the figure as verified"]'::jsonb,2),
  ('grants-7','grants',7,'The grant draft is saved and assigned for review. Does that authorize submission?','["Yes, because the document has a title","Yes, if a volunteer prepared it","Yes, after adding an HPG logo","No; check the submission authority and required reviewers"]'::jsonb,3),
  ('grants-8','grants',8,'A donor requires restricted use of funds for one named program. How should the grant writer handle it?','["Document and preserve the stated restrictions in the budget and agreement","Treat the funding as unrestricted operating revenue","Use the funds for unrelated projects","Leave restrictions out of the application"]'::jsonb,0),
  ('communications-4','communications',4,'An approved interview contains a photograph whose usage rights are unresolved. What must happen?','["Obtain and review the image-specific rights evidence before releasing it","Assume interview consent covers every image","Publish it privately on social media first","Mark rights cleared because an editor likes it"]'::jsonb,0),
  ('communications-5','communications',5,'A story''s factual claim is disputed after drafting. Which stage is necessary?','["Wait for a social-media response","Resolve and document independent fact checking before release","Move it directly to published status","Remove the dispute without correction"]'::jsonb,1),
  ('communications-6','communications',6,'A magazine has a planned release date but one article is embargoed. What is valid?','["Bypass the embargo with a different URL","Copy private source files into a public folder","Review and prepare the internal proof without violating the embargo","Publish the issue immediately"]'::jsonb,2),
  ('communications-7','communications',7,'What distinguishes a magazine design proof from an actual release?','["The proof automatically posts every article","The proof counts as a signed consent form","There is no distinction","The proof supports internal review; release requires final governed authorization"]'::jsonb,3),
  ('communications-8','communications',8,'Who should clear private media rights after a staff member uploads a recording?','["A separately authorized reviewer following evidence requirements","The uploader automatically","Any external reader","A social scheduler without rights access"]'::jsonb,0),
  ('marketing-4','marketing',4,'A campaign has been marked scheduled internally. What does this prove about external platforms?','["Only the internal schedule; external publication requires separate evidence","That it was posted to every connected social account","That its engagement has been measured","That a donor approved it"]'::jsonb,0),
  ('marketing-5','marketing',5,'A new social post contains an identifiable beneficiary. What is required before release?','["Ask an unverified social account for approval","Check specific rights and consent and the required approval path","Post first and seek permission later","Crop out the organization''s logo"]'::jsonb,1),
  ('marketing-6','marketing',6,'Why link a post to a registered channel account?','["To replace legal rights review","To waive editorial approvals","To identify the intended platform and owner without assuming valid publishing credentials","To guarantee automatic publication"]'::jsonb,2),
  ('marketing-7','marketing',7,'A campaign changes its budget after Finance review. What is the appropriate next step?','["Keep the earlier approval regardless","Hide the change in notes","Publish the campaign immediately","Reconcile the changed amount with the approval workflow"]'::jsonb,3),
  ('marketing-8','marketing',8,'A marketing officer wants to report clicks but has only a draft post. What is accurate?','["No verified external click metric exists from the draft alone","Use estimated impressions as actual clicks","Mark the post as viral","Copy metrics from an unrelated campaign"]'::jsonb,0),
  ('research-4','research',4,'Two publications disagree about a primary source''s meaning. What should a researcher do?','["Distinguish original evidence, method and later interpretation before drawing a conclusion","Select the more popular headline","Describe both interpretations as proven facts","Remove source dates"]'::jsonb,0),
  ('research-5','research',5,'An archival document has incomplete provenance. How should it be described?','["Invent a collection number","Identify the provenance gap and avoid overstating authenticity","Declare it independently authenticated","Treat a secondary blog as the original"]'::jsonb,1),
  ('research-6','research',6,'A translated quotation is used in a proposal. What should accompany it?','["A claim that all translations are identical","No attribution","The source, translator or edition, and relevant contextual limitations","Only a memorable phrasing"]'::jsonb,2),
  ('research-7','research',7,'A colleague uploads a restricted research interview transcript. What must be checked?','["That it can be indexed publicly","That it has a short filename","That no reviewer will ask","The authorized purpose, subject permission and access scope"]'::jsonb,3),
  ('research-8','research',8,'A small observational dataset supports a correlation. What is the defensible wording?','["Describe the observed association without claiming causation unsupported by design","Say one variable caused the other","Remove limitations","Report a perfect prediction"]'::jsonb,0),
  ('budget-4','budget',4,'A proposed disbursement uses a budget category without sufficient detail. What should Finance request?','["Itemization and evidence connecting it to the approved purpose","Only a new logo","An informal promise to add detail later","A public appeal for funds"]'::jsonb,0),
  ('budget-5','budget',5,'A budget and actuals report shows a variance. What should the reviewer identify?','["An assumption that the variance is fraud","Amount, period, source transactions and a supported explanation","Only the color of the chart","A convenient replacement number"]'::jsonb,1),
  ('budget-6','budget',6,'Can a program coordinator transfer restricted funds merely because they drafted a budget?','["Yes, if a colleague requests it in chat","Yes, if the project is urgent","No; disbursement follows authorized controls and restrictions","Yes, if the amount is under a threshold they choose"]'::jsonb,2),
  ('budget-7','budget',7,'A new expense would exceed an approved allocation. What is appropriate?','["Change the receipt to fit the budget","Omit the expense from the ledger","Treat the overspend as an unrelated donation","Escalate for documented review and authorized budget adjustment"]'::jsonb,3),
  ('budget-8','budget',8,'A multi-currency budget has missing exchange-rate assumptions. Why does this matter?','["Comparability and authorization depend on documented conversion assumptions","Currency has no effect on reporting","The conversion can always be guessed","Only the title of the budget matters"]'::jsonb,0),
  ('accounting-4','accounting',4,'A receipt amount does not match its bank transaction. What should happen?','["Investigate and document the discrepancy before reconciliation","Modify the receipt image","Ignore the difference","Delete the statement"]'::jsonb,0),
  ('accounting-5','accounting',5,'When is a transaction entry supported for reporting?','["When it appears in a spreadsheet","When its period, account, source and required review can be traced","When the description sounds plausible","When the amount is rounded"]'::jsonb,1),
  ('accounting-6','accounting',6,'An NGO submits local contribution records in a different currency. What should the reviewer do?','["Discard the local currency","Post the total without identifying source","Apply the documented reporting and conversion approach with traceable evidence","Assume the amounts are USD"]'::jsonb,2),
  ('accounting-7','accounting',7,'A month-end reconciliation has unresolved items. What is appropriate?','["Mark the month fully reconciled without evidence","Remove outstanding transactions","Create balancing entries without explanation","Keep exceptions visible and escalate according to close controls"]'::jsonb,3),
  ('accounting-8','accounting',8,'Why should a journal-entry correction preserve a reason and audit record?','["To maintain traceability of who changed what and why","Because a correction eliminates all prior history","To avoid the approval process","To make an external grant application longer"]'::jsonb,0),
  ('board-4','board',4,'A proposed motion appears on a draft agenda. Can eligible directors vote already?','["No; a governed meeting and motion must be opened under the prescribed process","Yes, if the chair has drafted the agenda","Yes, through a public survey","Any participant may vote"]'::jsonb,0),
  ('board-5','board',5,'A director has a conflict involving the work item under consideration. What is appropriate?','["Delete the source work item","Follow the documented recusal requirements","Vote on behalf of the project owner","Ignore the conflict if the proposal is beneficial"]'::jsonb,1),
  ('board-6','board',6,'What is required before closing a live Board motion?','["An unrecorded verbal consensus","An uploaded photo of attendees","Applicable recorded quorum and voting thresholds","One positive comment"]'::jsonb,2),
  ('board-7','board',7,'Can the author of meeting minutes approve the same minutes unilaterally?','["Yes, if the author is senior","Yes, after printing them","Yes, if the meeting was short","No; independent eligible director approval is required"]'::jsonb,3),
  ('board-8','board',8,'How are approved minutes connected to follow-up actions?','["Authorized assignments create traceable workspace work items with owners and due dates","They automatically transfer funds","They immediately update public bylaws","They bypass the staff task system"]'::jsonb,0),
  ('hr-1','hr',1,'A volunteer applicant asks for access to sensitive employee records. What comes first?','["Email the entire employee directory","Verify appointment, role and authorization through HR and IT","Share an administrator account","Grant temporary access without evidence"]'::jsonb,1),
  ('hr-2','hr',2,'What is the distinction between a submitted application and an active staff appointment?','["Submission creates finance privileges","A resume is a signed employment agreement","An approved appointment and onboarding steps remain necessary","They are always equivalent"]'::jsonb,2),
  ('hr-3','hr',3,'A former staff member still has access to restricted modules. What is appropriate?','["Keep all privileges indefinitely","Erase the person''s audit history","Ask another staff member to use the account","Follow documented offboarding, permission review and audit procedures"]'::jsonb,3),
  ('hr-4','hr',4,'What does an Academy practice completion demonstrate?','["A learner self-reported completing instructions, not verified job proficiency","Independent professional licensure","Automatic promotion","HR clearance to access every department"]'::jsonb,0),
  ('hr-5','hr',5,'Who should evaluate formal performance evidence?','["A prospective applicant","An authorized supervisor or HR reviewer within the approved process","The learner alone","Any anonymous website visitor"]'::jsonb,1),
  ('program-1','program',1,'An NGO has four projects. Why must a program assignment identify a specific project when appropriate?','["To bypass NGO-level approval","To attach owners, budgets and evidence to the correct delivery scope","Project identity never affects records","To combine all projects into one receipt"]'::jsonb,1),
  ('program-2','program',2,'An NGO''s portal account exists but sponsorship is still under review. What is accurate?','["A public donation campaign makes the agreement active","The account alone authorizes disbursement","Portal registration and sponsor approval are distinct stages","The NGO is fully approved"]'::jsonb,2),
  ('program-3','program',3,'A program report claims an outcome but lacks supporting documentation. What should happen?','["Publish the claim as verified","Delete unfavorable data","Add a fictional example as a real result","Seek verifiable source evidence and distinguish pending findings"]'::jsonb,3),
  ('program-4','program',4,'Which item belongs in a program handoff?','["Deliverable, owner, due date, current evidence and authorized next reviewer","Only the organization''s logo","An unrelated grant number","An unsigned statement of completion"]'::jsonb,0),
  ('program-5','program',5,'A program budget changes after an approved sponsorship agreement. What must be reviewed?','["Whether the new amount fits the screen","Alignment with funding terms and the required Finance/Program approvals","Only the color palette","A social-media calendar"]'::jsonb,1),
  ('operations-1','operations',1,'A task is marked blocked because another department has not approved a prerequisite. What next?','["Transfer another team''s privileges","Identify the dependency, owner and evidence needed for escalation","Mark it complete anyway","Delete the predecessor"]'::jsonb,1),
  ('operations-2','operations',2,'Why should a project milestone have an accountable owner?','["To replace supporting evidence","To automatically change the grant status","To establish responsibility, review and follow-up","To guarantee the outcome already occurred"]'::jsonb,2),
  ('operations-3','operations',3,'A calendar deadline appears to conflict with a confirmed partner meeting. What is appropriate?','["Unilaterally move every attendee","Delete both events","Assume the external partner is available","Verify constraints with the responsible organizers before changing commitments"]'::jsonb,3),
  ('operations-4','operations',4,'What should a staff member do before closing a cross-functional handoff?','["Confirm required inputs, reviewer and downstream acceptance","Change the status without notifying the receiving owner","Use an unrelated completed task as proof","Remove the audit history"]'::jsonb,0),
  ('operations-5','operations',5,'A task''s owner has left the organization. What is the safer approach?','["Delete the task","Reassign through authorized management while retaining history","Use the former owner''s login","Change all deadlines to today"]'::jsonb,1),
  ('technology-1','technology',1,'A support email requests an administrator password. What should IT do?','["Forward access details to the whole team","Verify requester identity and avoid sharing credentials; follow approved recovery procedure","Reply with the password","Disable audit logging"]'::jsonb,1),
  ('technology-2','technology',2,'What best describes least-privilege authorization?','["All contractors receive super-admin access","Permissions are granted based on who asks first","Access only to functions necessary for approved duties","Every staff member can view private NGO bank details"]'::jsonb,2),
  ('technology-3','technology',3,'A workflow deployment passes a code build but its live staff permissions were not tested. What is accurate?','["All users must be able to use it","Its database is automatically compliant","Every external integration is connected","Build validation is not proof of authenticated end-to-end acceptance"]'::jsonb,3),
  ('technology-4','technology',4,'Why should an access change leave an audit trail?','["It supports accountability, investigation and authorized review","It replaces user identity verification","It means no approval is needed","It automatically publishes a public report"]'::jsonb,0),
  ('technology-5','technology',5,'An external integration is failing. What is the appropriate first step?','["Recreate the database without a backup","Check the affected service, error, scope and authorized logs without exposing secrets","Put API tokens into a support chat","Turn off all access controls"]'::jsonb,1),
  ('administration-1','administration',1,'An unsigned internal agreement draft is stored in Documents. What may staff claim?','["The Board has voted","It is a draft pending required approvals and signatures","It is enforceable solely because it is uploaded","All parties have accepted it"]'::jsonb,1),
  ('administration-2','administration',2,'A meeting invitation crosses several countries. What should the organizer verify?','["No meeting agenda","Every attendee''s bank account","Date, time zone, participants, purpose and approved distribution","Only the organizer''s local time"]'::jsonb,2),
  ('administration-3','administration',3,'What distinguishes an agenda action item from a Board-approved decision?','["Agenda placement is always approval","The meeting title determines the outcome","A staff email can amend the bylaws","The decision requires the applicable governed approval and record"]'::jsonb,3),
  ('administration-4','administration',4,'A department monthly report includes unresolved requests. What is accurate?','["Separate completed evidence from open issues and proposed follow-up","Report all requests as completed","Delete the unresolved section","Attribute results to unrelated departments"]'::jsonb,0),
  ('administration-5','administration',5,'When saving sensitive agreements, what should be preserved?','["A public search index","Appropriate access, version, responsible approval and signed final copy","Only a screenshot","An edited final copy without history"]'::jsonb,1),
  ('compliance-1','compliance',1,'What is the status of a drafted policy that has not passed its required approvals?','["An external certification","Draft or under review, not an operative approved control","Automatically effective","A signed sponsorship agreement"]'::jsonb,1),
  ('compliance-2','compliance',2,'A risk report cites an audit event but has no underlying context. What is appropriate?','["Erase the event","Publish the allegation as fact","Investigate original evidence before deciding what the event means","Declare wrongdoing immediately"]'::jsonb,2),
  ('compliance-3','compliance',3,'A fiscal sponsor receives restricted funding. What should compliance check?','["Only the campaign title","Whether a volunteer likes the request","An unverified verbal promise","Applicable donor conditions, sponsor controls, reporting and authorization"]'::jsonb,3),
  ('compliance-4','compliance',4,'An internal reviewer helped prepare the item being approved. What may be necessary?','["An independent reviewer or conflict management procedure","Self-approval by default","Deletion of the source document","Public voting by NGO clients"]'::jsonb,0),
  ('compliance-5','compliance',5,'What should happen when consent evidence expires?','["Publish the original private consent document","Review current permission and restrict reuse until the necessary consent is valid","Keep claiming perpetual permission","Change the date in the evidence"]'::jsonb,1),
  ('improvement-1','improvement',1,'An improvement proposal claims a 40 percent time saving without baseline observations. What should happen?','["Delete the original process description","Document the baseline and measurement method before treating the claim as verified","Publish the number as fact","Replace the percentage with a higher number"]'::jsonb,1),
  ('improvement-2','improvement',2,'A pilot changes access to sensitive systems. Which safeguard is essential?','["Share privileged credentials for convenience","Disable approval records","Authorized review and a rollback approach before implementation","Skip testing entirely"]'::jsonb,2),
  ('improvement-3','improvement',3,'What makes a process change measurable?','["A compelling slogan","A chart without labels","An unspecified future benefit","A defined indicator, observation period and source evidence"]'::jsonb,3),
  ('improvement-4','improvement',4,'Who should approve transferring a trial into normal operations?','["The accountable operational owner and required control reviewers","Any observer of the trial","A single anonymous survey response","A vendor without an agreement"]'::jsonb,0),
  ('improvement-5','improvement',5,'What should a post-implementation review distinguish?','["A roadmap from a signed report","Deployed functionality, observed results, unresolved risks and formal acceptance","A build passing from every other outcome","All open risks as resolved"]'::jsonb,1)
